INSERT INTO `events` (`id`, `evn_id`, `evn_title`, `evn_link`, `evn_img`, `evn_desc`, `evn_loc`, `evn_start`, `evn_end`, `evn_time`, `evn_date`, `created_at`, `updated_at`, `evn_stat`) VALUES
(1, '2XC4CWQW', 'WINAC2025 - FROM GLORY TO GLORY', NULL, 'events/BrdO0TvdnskIYkicUqIJWXF10AyMjksN22AjrFSm.jpg', 'WINNAC 2025🎉🎉🎉🥳\r\nWINNAC is an annual program established as our national convention which commemorates the rooted word of God, launches and prepares us for our next level and year ahead.\r\nThis highly anticipated glory, would be featuring our father Rev. Mike Eniola, Pst Becky Eniola and several anointed vessels of God.\r\nCome and take a turn, transition and settlement of from Glory to glory.\r\nDo not forget to come with your white handkerchief serving as a symbol of glorious praise.\r\nIt is essential as a member to support the program with our prayers, finance, presence and stewardship.\r\nYou will not be found missing🙏\r\nGod bless you,\r\nShalom❤️', 'His Glory Cathedral, Winners Avenue, After The WAEC Office Along Crusher Road, Lokoja Kogi State', '2025-11-25', '2025-11-30', 'Tuesday 5pm, Wednesday to Saturday [ 9am Morning Session, 5pm Evening Session ], Sunday 8am', NULL, '2025-11-21 08:23:02', '2025-11-24 14:56:01', 1),
(2, 'YGYJYTZJ', 'WINNAC2026', NULL, 'events/l6Bch4NwzdFuegJxZFEM5zIbOMJUaVtJ1kna9lga.jpg', 'WINNAC 2026', 'His Glory Cathedral, Habitation of Winners Ministries Inc.', '2026-11-24', '2026-11-29', '9am Daily', NULL, '2026-11-25 16:39:12', '2026-11-25 16:39:12', 1);
