(1, 'GA8AMERN', 'WINAC 2025', 'General', NULL, 'programmes/ThLMEZn1TLoWLjAMHhxaWcW3NA5tPjbul858p0sb.jpg', 'WINNAC 2025🎉🎉🎉🥳\r\nWINNAC is an annual program established as our national convention which commemorates the rooted word of God, launches and prepares us for our next level and year ahead.\r\nThis highly anticipated glory, would be featuring our father Rev. Mike Eniola, Pst Becky Eniola and several anointed vessels of God.\r\nCome and take a turn, transition and settlement of from Glory to glory.\r\nDo not forget to come with your white handkerchief serving as a symbol of glorious praise.\r\nIt is essential as a member to support the program with our prayers, finance, presence and stewardship.\r\nYou will not be found missing🙏\r\nGod bless you,\r\nShalom❤️', 'His Glory Cathedral, Winners Avenue, After The WAEC Office Along Crusher Road, Lokoja Kogi State', '2025-11-25', '2025-11-30', 'Tuesday 5pm, Wednesday to Saturday [ 9am Morning Session, 5pm Evening Session ], Sunday 8am', NULL, '2025-11-24 11:56:57', '2025-11-24 14:55:12', 1),
(3, '7OBLKGTE', 'Jordan & Israel Pilgrimage', 'General', NULL, 'programmes/IVOkIhnzpUmaCNyo75eq4SotF2Ws8zZsCCCdfvGn.jpg', 'Jordan & Israel Pilgrimage', 'Jordan & Israel', '2026-03-17', '2026-03-27', 'All Day', NULL, '2025-12-27 23:57:04', '2025-12-27 23:57:04', 1),
(4, 'F8JAKQUQ', 'WINNAC2026', 'General', NULL, 'programmes/FlKn52ArdBEy8whISggLuJgVHOSHhjaZDrmxGxP8.jpg', 'WINNAC 2026', 'Habitationon of Winners Minstries Inc', '2026-11-24', '2026-11-29', '9am Daily', NULL, '2026-11-25 16:58:31', '2026-11-25 16:58:31', 1);
